fit_expected<gmm::Weight>
dls_weight(const model::ModelEvaluator& ev, const data::SampleStats& samp,
           const data::RawData& raw, const Eigen::VectorXd& theta0,
           DlsWeightOptions opts) {
  if (!(opts.a >= 0.0 && opts.a <= 1.0)) {
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        "dls_weight: mixing scalar a must be in [0, 1]"));
  }

  // Evaluate at theta0 once — only to fix the moment layout (block
  // dimensions, whether the model carries mean structure).
  auto eval0 = ev.evaluate(theta0, false, false);
  if (!eval0.has_value()) {
    return std::unexpected(make_err(FitError::Kind::NonPositiveDefiniteSigma,
        "dls_weight: theta0: " + eval0.error().detail));
  }
  const model::ImpliedMoments& m = eval0->moments;

  if (samp.S.size() != m.sigma.size()) {
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        "dls_weight: SampleStats and model block counts differ"));
  }
  auto shapes = validate_dls_raw_shapes(samp, raw, "dls_weight");
  if (!shapes.has_value()) return std::unexpected(shapes.error());

  // Mean structure is present only when both the model and the sample carry
  // means — the same rule `gmm::residuals` uses for the moment layout.
  bool has_means = false;
  for (std::size_t b = 0; b < m.sigma.size(); ++b) {
    if (b < m.mu.size() && m.mu[b].size() > 0 && b < samp.mean.size() &&
        samp.mean[b].size() > 0) {
      has_means = true;
    }
  }

  gmm::Weight W;
  W.reserve(samp.S.size());
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const Eigen::MatrixXd& S = samp.S[b];
    const Eigen::MatrixXd& X = raw.X[b];
    const Eigen::Index p     = S.rows();
    const Eigen::Index pstar = p * (p + 1) / 2;

    // Γ_NT (from S) — needed in both meanstructure branches below.
    auto g_nt = data::gamma_nt(S);
    if (!g_nt.has_value()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "dls_weight: block " + std::to_string(b) + ": " +
          g_nt.error().detail));
    }

    if (has_means) {
      // Browne-1984 stacked NACOV for `s = [m̄; vech(S)]`. The NT side has
      // a zero mean–vech cross-block (third moments vanish under MVN) so
      // Γ_NT_full is the block diagonal blockdiag(S, Γ_NT). The ADF side
      // is the full empirical stacked NACOV — its cross-block carries
      // the population third moments. Interpolate at the matrix level
      // and invert the whole (p+p*) × (p+p*) result; at a = 0 this
      // collapses to W = blockdiag(S⁻¹, Γ_NT⁻¹) bit-identically to the
      // old per-block path.
      Eigen::MatrixXd gamma_nt_full =
          Eigen::MatrixXd::Zero(p + pstar, p + pstar);
      gamma_nt_full.topLeftCorner(p, p)             = S;
      gamma_nt_full.bottomRightCorner(pstar, pstar) = *g_nt;

      auto g_adf_full = data::empirical_gamma_with_means(X);
      if (!g_adf_full.has_value()) {
        return std::unexpected(make_err(FitError::Kind::NumericIssue,
            "dls_weight: block " + std::to_string(b) + ": " +
            g_adf_full.error().detail));
      }
      const Eigen::MatrixXd gamma_dls_full =
          (1.0 - opts.a) * gamma_nt_full + opts.a * (*g_adf_full);

      auto inv_full = gmm::equilibrated_weight_inverse(gamma_dls_full);
      if (!inv_full.ok) {
        return std::unexpected(make_err(FitError::Kind::NumericIssue,
            gamma_singular_detail(b, "stacked Gamma", inv_full)));
      }
      {
        auto bw = gmm::BlockWeight::dense(inv_full.inverse,
            FitError::Kind::NumericIssue,
            "dls_weight: block " + std::to_string(b));
        if (!bw.has_value()) return std::unexpected(bw.error());
        bw->set_cancels_measurement_units();
        W.push_back(std::move(*bw));
      }
      continue;
    }

    // Vech-only path (no meanstructure) — unchanged from prior behaviour:
    // mix the two p* × p* Γ matrices and invert.
    auto g_adf = data::empirical_gamma(X);
    if (!g_adf.has_value()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "dls_weight: block " + std::to_string(b) + ": " +
          g_adf.error().detail));
    }
    const Eigen::MatrixXd gamma_dls =
        (1.0 - opts.a) * (*g_nt) + opts.a * (*g_adf);

    // W_DLS = Γ_DLS⁻¹. At a = 0 this equals gmm::normal_theory_weight's
    // covariance block (its 0.5 scaling cancels the symmetric-basis factor 2).
    auto inv_mix = gmm::equilibrated_weight_inverse(gamma_dls);
    if (!inv_mix.ok) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          gamma_singular_detail(b, "mixed Gamma", inv_mix)));
    }
    {
      auto bw = gmm::BlockWeight::dense(inv_mix.inverse,
          FitError::Kind::NumericIssue,
          "dls_weight: block " + std::to_string(b));
      if (!bw.has_value()) return std::unexpected(bw.error());
      bw->set_cancels_measurement_units();
      W.push_back(std::move(*bw));
    }
  }
  return W;
}

